// Each skill has an explicit windup, trajectory, impact and bounded visual budget.
export const CLASS_VFX={VIG:{color:'#63ffc4',shape:'arrow'},ESP:{color:'#c290ff',shape:'daggers'},ARC:{color:'#82ddff',shape:'comet'},BAS:{color:'#ffda7a',shape:'shield'},RUP:{color:'#ff8cbd',shape:'quake'},DUE:{color:'#b0f7ff',shape:'cross'},LAS:{color:'#d79aff',shape:'crescent'}};
export function skillBlueprint(classId,index,skill){const style=CLASS_VFX[classId];return{...style,index,name:skill.name,windup:skill.cast||.12,flight:['shot','spell','dispel','rune'].includes(skill.kind),duration:index===6?1.2:.7,rays:Math.min(16,6+index),radius:index===6?80:32+index*4,impact:skill.coef>0?'dano após trajetória':'suporte no personagem',stun:skill.stun||0};}
export function drawSkillBlueprint(g,fx,a,b,time){const p=fx.blueprint,q=1-fx.life/fx.max,k=1-q;if(!p)return;g.save();g.globalCompositeOperation='lighter';g.strokeStyle=p.color;g.fillStyle=p.color;g.lineCap='round';g.lineWidth=1.8*k;g.globalAlpha=k*.85;
 const x=p.flight?a.x+(b.x-a.x)*q:b.x,y=p.flight?a.y+(b.y-a.y)*q:b.y,r=p.radius*(.35+q*.75);g.translate(x,y-22);
 if(p.flight){g.rotate(Math.atan2(b.y-a.y,b.x-a.x));for(let n=0;n<3;n++){g.globalAlpha=k*(.7-n*.15);g.beginPath();g.moveTo(-25-n*12,n*3-3);g.quadraticCurveTo(-5,-12+n*6,12,0);g.quadraticCurveTo(-5,12-n*6,-25-n*12,n*3-3);g.stroke();}g.fillStyle='#fff';g.beginPath();g.arc(8,0,3,0,Math.PI*2);g.fill();}
 else if(['daggers','cross','crescent','quake'].includes(p.shape)){for(let n=0;n<(p.shape==='cross'?2:3);n++){g.save();g.rotate(n*Math.PI*.65+q*2);g.beginPath();g.ellipse(0,0,r,r*.45,0,.2,Math.PI*1.5);g.stroke();g.restore();}}
 else{for(let n=0;n<3;n++){g.beginPath();g.ellipse(0,-n*8*q,r*(1-n*.15),r*.35, time*.3+n,0,Math.PI*2);g.stroke();}}
 for(let n=0;n<p.rays;n++){const angle=n*Math.PI*2/p.rays+q*.6,rr=r*(.5+q*.4);g.globalAlpha=k*.65;g.beginPath();g.moveTo(Math.cos(angle)*rr,Math.sin(angle)*rr*.5);g.lineTo(Math.cos(angle)*(rr+8),Math.sin(angle)*(rr+8)*.5);g.stroke();}g.restore();}
